const fs = require('fs');
const ENV = (n) => (typeof $env !== 'undefined' && $env[n]) || '';
const Q = '/home/node/.n8n/queue/publish';
const STATE = '/home/node/.n8n/state';
const LOGD = '/home/node/.n8n/logs';
const VK_STATE = STATE + '/vk_token.json';
const VK_STATUS = STATE + '/vk_status.json';
const LEDGER = STATE + '/published.jsonl';
// issue #1 scope: only the VK driver is live. Other platforms are
// moved to skipped/ until their drivers ship (FB/LI/IG/TikTok).
// Single source with the ENABLED gate in sp-tg-moderation's Handle TG
// Update: both read the PUBLISH_PLATFORMS env var (comma-separated,
// injected via docker-compose.yml). Default 'vk' preserves the
// pre-env behavior when the var is unset.
// 'all' is the content-gen fan-out token (MAP.all -> every writer) -
// expand it here the same way Handle TG Update does, or
// PUBLISH_PLATFORMS=all generates drafts this gate can only park in
// skipped/ forever. Keep this list in sync with MAP in
// sp-content-gen's Generate Drafts.
const ALL_PLATFORMS = ['linkedin', 'facebook', 'fb', 'vk'];
// alias canonicalization: content-gen pins every draft's platform to
// role.replace('writer-', '') - 'fb' for writer-fb - while
// PUBLISH_PLATFORMS documents the 'facebook' spelling (content-gen's
// MAP accepts both). Without one canonical key an enabled 'facebook'
// can never match an 'fb' draft: the tick would park it in skipped/
// and the Approve gate would refuse it as disabled. Every ENABLED
// write AND lookup must go through canonPlat() - keep this map in
// sync with MAP in sp-content-gen's Generate Drafts and with the
// identical gate block in the sibling workflow.
const PLATFORM_ALIAS = { facebook: 'fb' };
const canonPlat = (p) => PLATFORM_ALIAS[p] || p;
const ENABLED = {};
for (const p of String(ENV('PUBLISH_PLATFORMS') || 'vk').split(',')) {
  const k = p.trim().toLowerCase();
  if (!k) continue;
  if (k === 'all') {
    for (const a of ALL_PLATFORMS) ENABLED[canonPlat(a)] = true;
  } else {
    ENABLED[canonPlat(k)] = true;
  }
}
for (const d of [Q, Q + '/done', Q + '/failed', Q + '/skipped',
  Q + '/processing', LOGD, STATE]) {
  try { fs.mkdirSync(d, { recursive: true }); } catch (e) {}
}
const token = ENV('TELEGRAM_BOT_TOKEN');
// operator chat_id is pinned config: TELEGRAM_CHAT_ID env first, the
// tg.json written by sp-tg-setup as compat fallback - never learned
// from incoming webhook updates (untrusted source)
let chatId = ENV('TELEGRAM_CHAT_ID') || null;
if (!chatId) {
  try { chatId = JSON.parse(fs.readFileSync(STATE + '/tg.json', 'utf8')).chat_id; } catch (e) {}
}
const tg = (m, b) => this.helpers.httpRequest({
  method: 'POST', url: 'https://api.telegram.org/bot' + token + '/' + m, body: b, json: true,
  // explicit timeout like vkCall below: an unbounded request that
  // hangs on api.telegram.org would stall the tick while it holds a
  // processing/ claim - stuck-claim recovery then reclassifies the
  // file as a crashed claim (~10min) even though the tick is alive
  timeout: 30000
});
const http = (o) => this.helpers.httpRequest(o);
const log = (r) => fs.appendFileSync(LOGD + '/publish.jsonl',
  JSON.stringify({ ts: new Date().toISOString(), ...r }) + '\n');
// atomic state writes: tmp file + rename, so a crash mid-write cannot
// leave a torn vk_status.json / vk_token.json behind. The tmp name is
// UNIQUE per call - a fixed 'p + .tmp' lets two overlapping ticks open
// the same staging file: the shorter second writeSync leaves the tail
// of the first payload behind, and the torn JSON is then renamed over
// the real state file. Same timestamp+random suffix discipline as the
// sibling writeJsonAtomic in sp-tg-moderation (no process.pid - the
// task-runner sandbox does not expose `process`).
// SYNC: sibling copies live in Handle TG Update, Prepare Draft and
// Compose Message (sp-tg-moderation), Generate Drafts
// (sp-content-gen) and Resolve Chat + Webhook (sp-tg-setup) - this
// is the hardened 0o600 variant, the others write plain. n8n Code
// nodes cannot share a prelude - replicate any fix to every copy.
// SYNC-BEGIN: write-json-atomic-hardened
const writeJsonAtomic = (p, obj) => {
  const tmp = p + '.tmp-' + Date.now().toString(36) + '-' +
    Math.random().toString(36).slice(2, 8);
  // the state dir is bind-mounted next to the SQLite DB and logs -
  // keep cached credentials (vk_token.json) and status files
  // owner-only. Apply the mode at creation: a writeFileSync +
  // later chmodSync leaves a window where a tmp file holding a live
  // VK token is group/world-readable under the default umask. The
  // chmod backstop covers reusing an older loose tmp file (the open
  // mode only applies to files this call creates).
  const fd = fs.openSync(tmp, 'w', 0o600);
  try {
    // writeSync may legally return a short byte count (interrupted
    // write, ENOSPC partial) - loop until the whole payload is on
    // disk before the rename publishes it, or a torn JSON lands over
    // a good state file. Buffer (not the string form) so multi-byte
    // chars cannot corrupt the offset math.
    const buf = Buffer.from(JSON.stringify(obj), 'utf8');
    let off = 0;
    while (off < buf.length) {
      off += fs.writeSync(fd, buf, off, buf.length - off);
    }
  } finally {
    fs.closeSync(fd);
  }
  try { fs.chmodSync(tmp, 0o600); } catch (e) {}
  fs.renameSync(tmp, p);
};
// SYNC-END: write-json-atomic-hardened
// per-file results for this tick. vk_status.json used to be
// last-file-wins, so a later 'ok' would hide an earlier auth_error
// from the same run - the end-of-tick write below merges them into
// {status: worst, files: [...]} instead
const tickFiles = [];
const vkStatus = (s, reason, file) => {
  tickFiles.push({ file: file || '', status: s, reason: reason || '' });
  try {
    // one schema for every write: the intermediate per-file write
    // carries the same keys as the end-of-tick merge below
    // ({status, ts, last_tick, file, reason, files}) - a reader must
    // never see a shape that depends on WHEN in the tick it read the
    // file. last_tick is the liveness heartbeat (== ts on a real
    // write); the empty-tick path below refreshes it alone
    const now = new Date().toISOString();
    writeJsonAtomic(VK_STATUS, {
      status: s, ts: now, last_tick: now, file: file || '',
      reason: reason || '', files: tickFiles
    });
  } catch (e) {}
};
// error strings can echo request details (failing URL, body); never
// let a raw access_token reach publish.jsonl, the ledger or Telegram.
// EVERY token value held this tick lands in KNOWN_TOKENS - masking
// only the active vkToken would still leak the env fallback or a
// superseded cached token when an error string echoes it.
// Same masking discipline as scrubSecrets in sp-tg-moderation
// (Handle TG Update), Generate Drafts (sp-content-gen) and
// sp-tg-setup - keep the >=8 length floor in sync across copies.
const KNOWN_TOKENS = new Set();
const scrub = (s) => {
  let out = String(s).replace(/access_token=[^&\s"']+/g, 'access_token=***');
  // a known token value can also surface bare (JSON dump, proxy
  // echo) - mask the literal string, not only the form-encoded shape.
  // Length floor: a short value matches common substrings and would
  // shred unrelated text (over-masking) - real VK tokens and the
  // refresh secret are far longer, so sub-8-char entries stay unmasked
  for (const tk of KNOWN_TOKENS) {
    if (tk && tk.length >= 8) out = out.split(tk).join('***');
  }
  return out;
};

// VK token: cached copy from the last refresh wins, env is the
// fallback - first at startup, then again as a last resort inside
// vkCall when the refresh service cannot mint a replacement.
const ENV_TOKEN = ENV('VK_ACCESS_TOKEN') || null;
if (ENV_TOKEN) KNOWN_TOKENS.add(ENV_TOKEN);
// the refresh-service shared secret rides the X-Shared-Token header
// on every /vk-token call - an httpRequest error that echoes request
// details (headers/config in the error object) would otherwise write
// it verbatim into publish.jsonl, vk_status.json and the Telegram
// summary. It gates an endpoint serving live wall-scope tokens, so it
// is masked like the tokens themselves.
const REFRESH_SECRET = ENV('VK_TOKEN_SECRET') || null;
if (REFRESH_SECRET) KNOWN_TOKENS.add(REFRESH_SECRET);
// the tg() URL embeds the bot token - a thrown httpRequest
// error can carry the request config (url included) into
// publish.jsonl, so mask it like the VK credentials
if (token) KNOWN_TOKENS.add(token);
let vkToken = null;
try { vkToken = JSON.parse(fs.readFileSync(VK_STATE, 'utf8')).access_token || null; } catch (e) {}
if (vkToken) KNOWN_TOKENS.add(vkToken);
if (!vkToken) vkToken = ENV_TOKEN;

// Host-side refresh: vk_token_service.py extracts a fresh web token from
// the logged-in VK Chrome tab via CDP. Container reaches the host through
// the slirp gateway 10.0.2.2 (rootless host-network quirk).
const REFRESH_URL = ENV('VK_TOKEN_REFRESH_URL') || 'http://10.0.2.2:8792/vk-token';
// /vk-token requires the shared-secret header (VK_TOKEN_SECRET) - a
// missing/empty env makes the service answer 401, surfaced below as
// 'token service unreachable' rather than a VK auth error
const REFRESH_HEADERS = REFRESH_SECRET
  ? { 'X-Shared-Token': REFRESH_SECRET } : {};
// A THROWN refresh error is normally a token-service outage - except a
// 503/{retryable:true} 'busy' answer, which only means another
// get_token() held the service lock past this call's budget (two
// overlapping ticks both refreshing on the same stale cached token hit
// this exact race). Busy is transient: the caller requeues the file for
// the next tick instead of parking it in failed/. The thrown error
// shape varies with the httpRequest wrapper (axios .response,
// NodeApiError .httpCode/.description, bare .statusCode), so probe all
// of them plus the serialized message.
const isBusyRefreshErr = (e) => {
  if (!e) return false;
  const status = Number(
    (e.response && e.response.status) || e.statusCode ||
    e.httpCode || e.status);
  if (status === 503) return true;
  const body = (e.response && e.response.data) || e.data || e.body;
  if (body && body.retryable === true) return true;
  const s = String(e.description || e.message || e);
  return /"retryable":\s*true|busy - another token request|status code 503/i
    .test(s);
};
// The HTTP status a thrown refresh error carries, 0 when the failure
// was transport-level (no answer ever arrived - ECONNREFUSED on a
// service restart, host reboot where n8n came up first, timeout,
// slirp gateway blip). The wrapper shapes vary like isBusyRefreshErr
// documents, and as a last resort the status can sit inside the
// message text ('Request failed with status code 502').
const refreshHttpStatus = (e) => {
  if (!e) return 0;
  const status = Number(
    (e.response && e.response.status) || e.statusCode ||
    e.httpCode || e.status);
  if (Number.isFinite(status) && status > 0) return status;
  const m = /status code (\d{3})/i
    .exec(String(e.description || e.message || e));
  return m ? Number(m[1]) : 0;
};
// Retryable refresh failure = the service gave no classified verdict:
// the 503/'busy' lock-contention answer OR a thrown transport error
// carrying no HTTP status (unreachable host). Both are transient and
// wall.post provably never ran in the paths that raise them (the
// no-token throw precedes any VK call; an error-5 rethrow was
// rejected by VK before posting), so the file can safely take the
// same link()-hand-back requeue as busy - BOUNDED by the t.retries
// cap in the tick's catch block. A thrown error WITH a non-503 HTTP
// status is the service's own classified answer (401 bad shared
// secret, 502 'token rejected' - it already decided retryable:false);
// honoring that dead-letters a misconfigured deploy immediately
// instead of burning the retry budget on a permanent failure.
const isRetryableRefreshErr = (e) =>
  isBusyRefreshErr(e) || !refreshHttpStatus(e);
async function vkRefresh() {
  const r = await http({ method: 'GET', url: REFRESH_URL, json: true, timeout: 60000,
    headers: REFRESH_HEADERS });
  if (r && r.ok && r.access_token) {
    vkToken = r.access_token;
    KNOWN_TOKENS.add(vkToken);
    writeJsonAtomic(VK_STATE, {
      access_token: vkToken, saved_at: new Date().toISOString(),
      source: r.source || 'refresh-service'
    });
    return true;
  }
  // a RESOLVED non-2xx body is possible whenever the httpRequest
  // wrapper stops throwing on HTTP errors (n8n version or config
  // change): a 503 {retryable:true} 'busy' answer landing here would
  // degrade to a plain 'returned no token' and the file would park in
  // failed/ instead of requeueing. Surface it as a thrown busy error
  // - isBusyRefreshErr reads .body.retryable, so both call sites
  // (the vkCall error-5 refresh and the publishVk no-token refresh)
  // reclassify it without further changes.
  if (r && r.retryable === true) {
    const e = new Error('vk token refresh: service busy - ' +
      scrub(JSON.stringify(r)).slice(0, 150));
    e.body = r;
    throw e;
  }
  return false;
}

async function vkCall(method, params) {
  // access_token travels in the POST body (form-encoded), never in the
  // URL - transport-level errors can echo the request URL back, which
  // would leak the token into logs and the Telegram summary.
  const call = async (t) => {
    const res = await http({
      method: 'POST',
      url: 'https://api.vk.com/method/' + method,
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: 'v=5.199&access_token=' + encodeURIComponent(t) + '&' + params,
      // explicit timeout: httpRequest's default is unbounded, so a hung
      // api.vk.com socket would stall the tick far past the 2-min
      // interval while holding the processing/ claim (the file then
      // looks like a crashed claim to stuck-claim recovery)
      timeout: 30000,
      json: true
    });
    // the VK schema promises an integer error_code, but a proxy or
    // shim in front of api.vk.com can answer it as a string ("5") -
    // the strict === 5 gate below would then skip the refresh+retry
    // branch and park a rejected-token file in failed/ without the
    // self-heal this mechanism exists for. vk_token_service.py
    // int()-normalizes the same code before its own == 5 check; the
    // n8n side shares that network path, so normalize here too -
    // once, so the gate AND every downstream e.vk_code === 5
    // classification read a number. An unparseable code keeps its
    // raw value: coercing it to NaN would turn a weird string code
    // falsy and misclassify it as a transport failure below.
    if (res && res.error) {
      const c = Number(res.error.error_code);
      if (!Number.isNaN(c)) res.error.error_code = c;
    }
    return res;
  };
  let r = await call(vkToken);
  let refreshErr = null;
  if (r && r.error && r.error.error_code === 5) {
    // expired/rejected token - pull a fresh one and retry once. A
    // THROWN refresh error (HTTP failure/timeout against the host
    // service) is a token-service outage, not a VK auth rejection:
    // keeping it lets the re-thrown error-5 below be reclassified as
    // token_service_down, so the operator restarts vk-token.service
    // instead of rotating VK credentials. A resolved-but-false
    // vkRefresh (service answered {ok:false}) stays an auth error -
    // the service is reachable, VK-side minting is what failed.
    let ok = false;
    try { ok = await vkRefresh(); } catch (e) { refreshErr = e; }
    if (ok) {
      r = await call(vkToken);
    } else if (ENV_TOKEN && ENV_TOKEN !== vkToken) {
      // refresh service unreachable or returned no token - last
      // resort: the env token may still be valid even when the
      // cached web-session token is not
      vkToken = ENV_TOKEN;
      r = await call(vkToken);
    }
  }
  if (r && r.error) {
    const e = new Error('vk ' + method + ': ' + scrub(JSON.stringify(r.error)).slice(0, 200));
    e.vk_code = r.error.error_code;
    if (refreshErr && e.vk_code === 5) {
      // this error-5 only stands because the refresh service could not
      // be reached - report the actionable failure (the VK code is
      // kept for the log line)
      e.token_service = true;
      e.refresh_error = scrub(refreshErr).slice(0, 150);
      // BOTH halves can be dead at once: when the token this error-5
      // came from IS the env fallback (the explicit ENV_TOKEN retry
      // above, or the env token was the only token on file from the
      // start), the env credential is rejected too - reporting just
      // 'token_service_down' sends the operator to restart
      // vk-token.service while VK_ACCESS_TOKEN in ENV is what needs
      // rotating. Flag the dual cause so the tick reports a distinct
      // status instead of masking it.
      if (ENV_TOKEN && vkToken === ENV_TOKEN) e.env_token_auth = true;
      // this error-5 only happened because the refresh service could
      // not deliver a verdict - VK rejected the token BEFORE wall.post
      // ran, so no post can be live. A transient refresh failure (busy
      // 503 or unreachable host - see isRetryableRefreshErr) requeues
      // the file for the next tick instead of parking it in failed/,
      // bounded by the t.retries cap there. A classified non-503
      // service answer stays terminal.
      e.retryable = isRetryableRefreshErr(refreshErr);
      if (isBusyRefreshErr(refreshErr)) e.busy = true;
    }
    throw e;
  }
  return r && r.response;
}

async function publishVk(t, fname) {
  const owner = ENV('VK_USER_ID');
  if (!owner) throw new Error('vk: VK_USER_ID not set');
  if (!vkToken) {
    let ok = false;
    let svcErr = null;
    try { ok = await vkRefresh(); } catch (e) { svcErr = e; }
    if (!ok) {
      // token service down / cannot mint a token - NOT a VK auth
      // rejection, so no vk_code=5: the operator needs to know which
      // side failed (host refresh service vs VK API). A busy
      // (503/retryable) answer is transient lock contention, and an
      // unreachable host (systemd restart, reboot, ECONNREFUSED) is
      // equally transient - wall.post provably never ran on either
      // path (no token -> no VK call at all), so the tick requeues the
      // file bounded by t.retries rather than failing it. Only a
      // classified non-503 service answer (isRetryableRefreshErr -
      // e.g. 502 'token rejected') or a resolved no-token answer stays
      // terminal.
      const busy = isBusyRefreshErr(svcErr);
      const e = new Error(svcErr
        ? 'vk: token service ' + (busy ? 'busy' : 'unreachable') +
          ': ' + scrub(svcErr).slice(0, 120)
        : 'vk: token service returned no token');
      e.token_service = true;
      if (svcErr && isRetryableRefreshErr(svcErr)) e.retryable = true;
      if (busy) e.busy = true;
      throw e;
    }
  }
  // `test` is a strict JSON boolean: only `test === true` triggers the
  // publish-verify-delete test path; "yes"/1 are treated as real posts.
  const isTest = t.test === true;
  // Minimal publish ledger - full registry is issue #12.
  const ledger = (r) => fs.appendFileSync(LEDGER, JSON.stringify({
    ts: new Date().toISOString(), id: t.id, platform: 'vk',
    test: isTest,
    media_ignored: Array.isArray(t.media) ? t.media.length : 0, ...r
  }) + '\n');
  // Orphan probe shared by both response-loss paths (a wall.post
  // transport error and a resolved response without post_id): if the
  // post did land, the newest wall items carry our exact text -
  // recover external_id into the ledger so the operator has the post
  // id instead of a blind "maybe". Best-effort; a probe failure
  // leaves maybe_live only.
  const probeOrphan = async () => {
    try {
      const got = await vkCall('wall.get',
        'owner_id=' + encodeURIComponent(owner) + '&count=5');
      // Exact-text match alone can attribute the WRONG post: if the
      // same text was published earlier (a re-approve of an
      // identical draft, a repost), the probe would record the old
      // post's id and the 'delete manually' note would point the
      // operator at it. Bound the match: the post must sit on OUR
      // wall (owner_id equals VK_USER_ID - a user wall can also
      // carry posts by others) AND be authored by us: authorship
      // lives in from_id, not owner_id - a third party's post on the
      // operator's wall carries the operator's owner_id too, so a
      // same-text post by someone else inside the window would be
      // misattributed as the orphaned wall.post. And be no older
      // than 10min - the failed wall.post either just landed or
      // never will, so a same-text post outside the window is a
      // different post. Newest match first.
      const winStart = Math.floor(Date.now() / 1000) - 600;
      const hit = ((got && got.items) || [])
        .filter((it) =>
          String(it.text || '') === String(t.text || '') &&
          String(it.owner_id) === String(owner) &&
          String(it.from_id) === String(owner) &&
          Number(it.date || 0) >= winStart)
        .sort((a, b) => Number(b.date || 0) - Number(a.date || 0))[0];
      return (hit && hit.id) ? owner + '_' + hit.id : null;
    } catch (e) { return null; }
  };
  // text-only first pass; media[] is carried in the queue file but not
  // attached yet (photos.getWallUploadServer flow is a follow-up)
  let res;
  try {
    res = await vkCall('wall.post',
      'owner_id=' + encodeURIComponent(owner) +
      '&message=' + encodeURIComponent(t.text || ''));
  } catch (e) {
    // Transport loss after the request was sent is the dangerous case:
    // wall.post may already have landed on VK's side and only the
    // response was lost (timeout/reset) - the file then goes to
    // failed/ with no post-created record and a re-approve would run
    // wall.post AGAIN = a duplicate live post. A definite VK error
    // body (vk_code set) means the call was rejected server-side, so
    // only transport/config failures get the flag.
    if (!e.vk_code && !e.token_service) {
      e.maybe_live = true;
      e.orphan_id = await probeOrphan() || undefined;
      if (e.orphan_id) {
        ledger({ status: 'maybe-live', external_id: e.orphan_id,
          note: 'wall.post response lost; matching text found on wall - ' +
            'treat as published, delete manually if unwanted' });
      }
    }
    throw e;
  }
  const postId = res && res.post_id;
  if (!postId) {
    // A resolved response WITHOUT post_id is the same ambiguity as a
    // lost one: VK answered, but nothing proves the post did NOT
    // land. Flag maybe_live so the failed/ move, the ledger record
    // and the warning text all carry it, and run the same orphan
    // probe the transport-loss path uses.
    const e = new Error('vk: wall.post returned no post_id');
    e.maybe_live = true;
    e.orphan_id = await probeOrphan() || undefined;
    if (e.orphan_id) {
      ledger({ status: 'maybe-live', external_id: e.orphan_id,
        note: 'wall.post response had no post_id; matching text found ' +
          'on wall - treat as published, delete manually if unwanted' });
    }
    throw e;
  }
  const ext = owner + '_' + postId;
  // ledger-first: external_id hits disk the instant wall.post returns,
  // BEFORE the verification call. A verify throw can no longer orphan
  // a live wall post with no recorded id.
  ledger({ status: 'post-created', external_id: ext });
  // post-publish verification: the post must read back from the wall.
  // A verify failure is recorded and tolerated - the post is live
  // either way and post-created above already holds the evidence.
  let verified = false;
  try {
    const got = await vkCall('wall.getById', 'posts=' + encodeURIComponent(ext));
    verified = !!(got && Array.isArray(got.items) &&
      got.items.length && Number(got.items[0].id) === Number(postId));
  } catch (e) {
    ledger({ status: 'verify-failed', external_id: ext, verified: false,
      verify_error: scrub(e).slice(0, 200) });
  }
  ledger({ status: 'published', external_id: ext,
    verified: verified, deleted: false });
  let status = 'published';
  let deleted = false;
  let deleteErr = null;
  // test drafts are published, verified, then deleted from the wall.
  // A delete failure is recorded as a second ledger record
  // (test-delete-failed + delete_error) and does not fail the file:
  // the records above already hold external_id.
  if (isTest) {
    try {
      const del = await vkCall('wall.delete',
        'owner_id=' + encodeURIComponent(owner) +
        '&post_id=' + encodeURIComponent(postId));
      // VK answers response:1 on success - a falsy/0 response means the
      // delete silently did not land even though no error was raised
      if (Number(del) !== 1) {
        throw new Error('wall.delete returned ' +
          scrub(JSON.stringify(del)).slice(0, 100));
      }
      deleted = true;
      status = 'test-published-deleted';
      ledger({ status: status, external_id: ext,
        verified: verified, deleted: true });
    } catch (e) {
      status = 'test-delete-failed';
      deleteErr = scrub(e).slice(0, 200);
      ledger({ status: status, external_id: ext,
        verified: verified, deleted: false, delete_error: deleteErr });
    }
  }
  // 'ok' only on full success: a failed test delete leaves a live test
  // post, an unverifiable post is not a clean publish - each gets its
  // own status instead of a silent 'ok'.
  if (deleteErr) vkStatus('test_delete_failed', deleteErr, fname);
  else if (!verified) vkStatus('publish_unverified', '', fname);
  else vkStatus('ok', '', fname);
  // media[] is carried in the queue file but not attached yet (the
  // photos.getWallUploadServer flow is a follow-up) - surface the drop
  // in the operator-facing result line too, not only the ledger's
  // media_ignored count: the moderation preview reports 'N/M photo(s)
  // attached', so a silent text-only post looks like lost attachments
  const mediaIgnored = Array.isArray(t.media) ? t.media.length : 0;
  return { status: status, via: 'vk api wall.post ' + ext +
    (verified ? ' verified' : ' UNVERIFIED') +
    (isTest ? (deleted ? ' +deleted' : ' DELETE-FAILED') : '') +
    (mediaIgnored ? ' media attached: ' + mediaIgnored +
      ' ignored (upload not supported yet)' : '') };
}

// housekeeping: files parked as *.stale-<ts> on claim and orphaned
// dot-tmp payloads accumulate forever otherwise - prune anything
// older than 24h once per tick
try {
  const cutoff = Date.now() - 24 * 3600 * 1000;
  for (const f of fs.readdirSync(Q + '/processing')) {
    // also sweep orphaned .<id>.tmp-* payloads: the approve-sync
    // write in sp-tg-moderation (Handle TG Update) stages its
    // dot-tmp inside processing/ before the atomic rename, so a
    // crash there strands it - the *.json claim pass below never
    // sees dot files
    if (!f.includes('.stale-') && !f.startsWith('.')) continue;
    try {
      const p = Q + '/processing/' + f;
      if (fs.statSync(p).mtimeMs < cutoff) {
        fs.unlinkSync(p);
        log({ file: f, status: 'stale-pruned' });
      }
    } catch (e) {}
  }
  for (const f of fs.readdirSync(Q)) {
    if (!f.startsWith('.')) continue;
    try {
      const p = Q + '/' + f;
      if (fs.statSync(p).mtimeMs < cutoff) fs.unlinkSync(p);
    } catch (e) {}
  }
  // orphaned writeJsonAtomic staging files in the state dir: a crash
  // between write and rename strands vk_token.json.tmp-* /
  // vk_status.json.tmp-* forever. Match the actual staging suffixes:
  // '.tmp-' (current unique names) plus the exact '.tmp' tail of
  // pre-unique-name leftovers - a bare '.tmp' substring match would
  // also unlink unrelated names like 'x.tmplate' or 'notes.tmpx'
  for (const f of fs.readdirSync(STATE)) {
    if (f.indexOf('.tmp-') === -1 && !f.endsWith('.tmp')) continue;
    try {
      const p = STATE + '/' + f;
      if (fs.statSync(p).mtimeMs < cutoff) fs.unlinkSync(p);
    } catch (e) {}
  }
  // same orphan pattern one level down in state/drafts/: Prepare
  // Draft and saveDraft stage '<id>.json.tmp-*' there, and a crash
  // between write and rename strands them - no reader ever touches
  // them again. Same tightened '.tmp-'/'.tmp'-tail match as the STATE
  // sweep above: drafts are user-visible names, so a broad '.tmp'
  // substring could unlink a real draft file
  try {
    for (const f of fs.readdirSync(STATE + '/drafts')) {
      if (f.indexOf('.tmp-') === -1 && !f.endsWith('.tmp')) continue;
      try {
        const p = STATE + '/drafts/' + f;
        if (fs.statSync(p).mtimeMs < cutoff) fs.unlinkSync(p);
      } catch (e) {}
    }
  } catch (e) { /* drafts dir absent - nothing to sweep */ }
  // terminal dirs grow unbounded - drop queue records older than 30
  // days once per tick. publish.jsonl + published.jsonl keep the
  // audit trail, so the payload file itself is not needed that long.
  const termCutoff = Date.now() - 30 * 24 * 3600 * 1000;
  for (const dir of ['done', 'failed', 'skipped']) {
    let pruned = 0;
    for (const f of fs.readdirSync(Q + '/' + dir)) {
      try {
        const p = Q + '/' + dir + '/' + f;
        if (fs.statSync(p).mtimeMs < termCutoff) {
          fs.unlinkSync(p);
          pruned++;
        }
      } catch (e) {}
    }
    if (pruned) log({ status: 'terminal-pruned', dir: dir, count: pruned });
  }
  // size-based log rotation: the jsonl logs grow forever otherwise
  // (the terminal queues above already prune at 30d). Over 5MB the
  // live file is renamed aside to <name>.1 - a single generation, a
  // previous .1 is replaced - and the next append starts a fresh
  // file. Renames are atomic and every writer appends by path, so a
  // mid-rotation append cannot be lost. state/published.jsonl stays
  // OUT of this on purpose: it is the append-only durable publish
  // evidence that publishedIds() in sp-tg-moderation indexes, and
  // truncating it would re-open duplicate wall.posts.
  const rotateIfBig = (p) => {
    try {
      if (fs.statSync(p).size > 5 * 1024 * 1024) {
        fs.renameSync(p, p + '.1');
        log({ file: p, status: 'log-rotated' });
      }
    } catch (e) {}
  };
  for (const lf of [LOGD + '/moderation.jsonl', LOGD + '/publish.jsonl',
    LOGD + '/content-gen.jsonl']) {
    rotateIfBig(lf);
  }
} catch (e) {}

// terminal moves: a failed rename (file removed externally, ENOSPC)
// must not abort the whole tick mid-loop - remaining queue files
// still need processing, so every move below goes through mv()
const mv = (from, to, what) => {
  try {
    // rename(2) silently replaces a same-name destination - a second
    // terminal move for one draft id would clobber the file already
    // parked in done//failed//skipped/ (the ledger keeps the audit
    // trail, but the payload is lost). Park the incoming file under a
    // unique suffix instead; probes only ever look for the bare
    // <id>.json name, so the original record still answers them.
    let dest = to;
    if (fs.existsSync(dest)) {
      // ms-resolution timestamp alone is not unique enough - two
      // collision-park moves of the same <id>.json inside one
      // millisecond would still clobber; add a random component
      dest = to + '.mv-' + Date.now().toString(36) + '-' +
        Math.random().toString(36).slice(2, 6);
      // label the fields by meaning, not by parameter name: `from`
      // here used to hold the INTENDED destination and `to` the
      // collision-parked name, which read backwards in the log
      log({ file: what || from, status: 'move-renamed',
        from: from, intended_to: to, parked_as: dest });
    }
    fs.renameSync(from, dest);
    return true;
  } catch (e) {
    log({ file: what || from, status: 'move-failed',
      from: from, to: to,
      error: String(e).slice(0, 150) });
    return false;
  }
};

const out = [];
// stuck-claim recovery: a plain *.json file left in processing/ means
// a tick died between the atomic claim rename and the terminal move
// (container restart, ENOSPC on mv). The root readdir below never
// sees it and every Approve keeps answering 'already queued' - the
// draft is blocked forever without this pass. Reclaim anything
// claimed more than 10min ago. ctimeMs - not mtime - is the claim
// timestamp: rename() bumps ctime while mtime keeps the original
// enqueue time, so a long-waiting queue file is not mistaken for a
// stuck claim, and 10min >> the 2min tick plus worst-case publish
// latency. Auto-retry is unsafe (wall.post may already have landed),
// so the file goes to failed/ with a ledger note; the operator
// checks the wall and re-approves through the normal requeue path.
try {
  const stuckCutoff = Date.now() - 10 * 60 * 1000;
  for (const f of fs.readdirSync(Q + '/processing')) {
    // *.stale-* files are pruned by the housekeeping pass above;
    // only a live claim ends in .json
    if (!f.endsWith('.json')) continue;
    const p = Q + '/processing/' + f;
    let st = null;
    try { st = fs.statSync(p); } catch (e) { continue; }
    if (st.ctimeMs > stuckCutoff) continue;
    let pid = null;
    let pplat = null;
    try {
      const pj = JSON.parse(fs.readFileSync(p, 'utf8'));
      pid = pj.id || null;
      pplat = pj.platform || null;
    } catch (e) {}
    if (!mv(p, Q + '/failed/' + f, f)) continue;
    const note = 'tick died between claim and terminal move - ' +
      'post may be live, check the VK wall before re-approving';
    log({ file: f, id: pid, platform: pplat,
      status: 'stuck-claim-recovered', note: note });
    try {
      fs.appendFileSync(LEDGER, JSON.stringify({
        ts: new Date().toISOString(), id: pid, platform: pplat,
        file: f, status: 'stuck-claim-recovered', maybe_live: true,
        note: note
      }) + '\n');
    } catch (e) {}
    out.push(f + ' recovered from stuck claim -> failed/ (post may be live)');
  }
} catch (e) {}
const files = fs.existsSync(Q) ? fs.readdirSync(Q).filter(f => f.endsWith('.json')) : [];
for (const f of files) {
  // claim the queue file atomically BEFORE any await: rename into
  // processing/. When two ticks overlap, the second one sees the file
  // gone (rename throws) and skips it - no double wall.post.
  const claimed = Q + '/processing/' + f;
  try {
    // a same-name file in processing/ is either a LIVE claim from a
    // concurrent tick mid-wall.post or a crashed claim's leftover -
    // and any *.json left here is younger than the 10min stuck window
    // by construction (the recovery pass above already reclaimed the
    // older ones). Moving a live claim aside breaks mutual exclusion:
    // the owner tick keeps publishing while this tick would rename
    // the queue file over the orphaned slot and wall.post it AGAIN.
    // Check the claim age first (ctimeMs - rename bumps ctime, same
    // clock the stuck-recovery pass uses): younger than the stuck
    // threshold means another tick owns it - SKIP the queue file and
    // leave the claim untouched; a later tick retries after the
    // owner resolves it. Only park the file as .stale-* once it is
    // past the threshold (a claim that slipped in between the
    // recovery pass and this loop, or whose recovery move failed).
    if (fs.existsSync(claimed)) {
      let cst = null;
      try { cst = fs.statSync(claimed); } catch (e) {}
      // cannot prove the claim is dead -> treat it as live and skip:
      // racing a rename over an active claim is the bug this guard
      // exists to prevent. The queue file stays put for a later tick.
      if (!cst || cst.ctimeMs > Date.now() - 10 * 60 * 1000) {
        log({ file: f,
          status: cst ? 'claim-skip-live' : 'claim-skip-unstattable' });
        continue;
      }
      mv(claimed, claimed + '.stale-' + Date.now(), f);
      log({ file: f, status: 'stale-claim-aside' });
    }
    fs.renameSync(Q + '/' + f, claimed);
  } catch (e) {
    // the expected failure here is rename contention with a
    // concurrent tick - ENOENT (the other tick claimed the
    // source first) or the EBUSY/EEXIST/ENOTEMPTY platform
    // variants of the same race: skip quietly. Anything else is
    // a persistent FS problem (EACCES on processing/, ENOSPC, a
    // wedged bind mount) that would skip this same queue file on
    // every tick forever, so it must leave a log line.
    const code = e && e.code;
    if (code !== 'ENOENT' && code !== 'EBUSY' &&
        code !== 'EEXIST' && code !== 'ENOTEMPTY') {
      log({ file: f, status: 'claim-failed',
        error: scrub(String((e && e.message) || e)).slice(0, 150) });
    }
    continue; // another tick already owns this file
  }
  let t;
  try {
    t = JSON.parse(fs.readFileSync(claimed, 'utf8'));
  } catch (e) {
    mv(claimed, Q + '/failed/' + f, f);
    log({ file: f, status: 'failed', error: 'bad json' });
    continue;
  }
  const p = canonPlat(String(t.platform || '').toLowerCase());
  if (!ENABLED[p]) {
    mv(claimed, Q + '/skipped/' + f, f);
    log({ id: t.id, platform: t.platform, status: 'skipped', reason: 'platform not enabled' });
    // vk_status.json is only written on the VK driver paths - a tick
    // whose every file lands here would leave the PREVIOUS tick's
    // status up forever, and a stale 'ok' (or worse, a stale
    // auth_error) reads as the current state. Record the skip so the
    // status file reflects this tick's outcome; 'skipped' ranks below
    // 'ok' in the end-of-tick merge, so it only becomes the headline
    // when the driver never ran at all.
    vkStatus('skipped', 'platform ' + (t.platform || '?') +
      ' not enabled', f);
    out.push((t.id || f) + ' ' + (t.platform || '?') + ' skipped (not enabled)');
    continue;
  }
  // an enabled platform with no driver (PUBLISH_PLATFORMS=all turns
  // on fb/linkedin, whose drivers are not shipped yet) passed the
  // Approve-side ENABLED gate and then used to park in failed/
  // forever on 'no driver for platform' - a terminal outcome for a
  // config-only gap. Park it in skipped/ like the not-enabled case;
  // a shipped driver plus a re-Approve revives it.
  if (p !== 'vk') {
    mv(claimed, Q + '/skipped/' + f, f);
    log({ id: t.id, platform: t.platform, status: 'skipped',
      reason: 'no driver for platform ' + p });
    vkStatus('skipped', 'no driver for platform ' + p, f);
    out.push((t.id || f) + ' ' + (t.platform || '?') +
      ' skipped (no driver for platform ' + p + ')');
    continue;
  }
  try {
    const r = await publishVk(t, f);
    mv(claimed, Q + '/done/' + f, f);
    // status mirrors the ledger: published / test-published-deleted /
    // test-delete-failed - not a flat 'published' for test drafts
    log({ id: t.id, platform: t.platform, via: r.via, status: r.status });
    out.push((t.id || f) + ' ' + t.platform + ' -> ' + r.via);
  } catch (e) {
    const errStr = scrub(e).slice(0, 300);
    // bound on retryable requeues: e.retryable marks transient
    // token-service failures where wall.post provably never ran
    // (busy lock contention or an unreachable host service - see
    // isRetryableRefreshErr and the throw sites), so the claim can
    // safely return to the queue root. But a host reboot or a wedged
    // vk-token.service can keep the error retryable for hours, and an
    // unbounded requeue would cycle claim -> requeue forever (plus a
    // tick report line every 2min). The queue payload carries the
    // count: bump t.retries and persist it on the claim inode BEFORE
    // the link() hand-back - link() shares the inode, so the requeued
    // root file keeps the running total across ticks. Past RETRY_MAX
    // the error falls through to the permanent failed/ move with an
    // explicit reason. A fresh re-Approve rebuilds the payload
    // without `retries` (the enqueue path in Handle TG Update) - an
    // explicit operator retry, so resetting the bound is intended.
    // The payload-sync paths there carry the counter through instead:
    // overwriting an existing queue file is a sync, not a new budget.
    const RETRY_MAX = 5;
    const prevTries = Number(t.retries);
    const tries =
      (Number.isFinite(prevTries) && prevTries > 0
        ? Math.floor(prevTries) : 0) + 1;
    const exhausted = !!(e && e.retryable) && tries > RETRY_MAX;
    if (e && e.retryable && !exhausted) {
      let persisted = false;
      try {
        t.retries = tries;
        // dot-tmp + rename like every other queue write: a torn
        // counter write must not reach the requeued file, and the dot
        // prefix puts a crash-orphaned staging file under the 24h
        // sweep of processing/ dot files above
        const rtmp = Q + '/processing/.' + f + '.rt-' +
          Date.now().toString(36) + '-' +
          Math.random().toString(36).slice(2, 6);
        fs.writeFileSync(rtmp, JSON.stringify(t, null, 2));
        fs.renameSync(rtmp, claimed);
        persisted = true;
      } catch (we) {
        log({ file: f, status: 'retry-counter-write-failed',
          error: String(we).slice(0, 120) });
      }
      if (persisted) {
        // transient token-service answer (busy 503 or unreachable -
        // see isRetryableRefreshErr). This is NOT a publish failure:
        // return the claim to the queue root so the NEXT tick retries
        // the file. failed/ is for terminal outcomes only - a
        // momentary outage must not permanently burn a publish.
        let note;
        try {
          // atomic exclusive hand-back - the same link(2) discipline
          // the enqueue path in Handle TG Update uses: link() fails
          // EEXIST instead of clobbering, so a fresh (edited) enqueue
          // landing between our publish attempt and this requeue is
          // never overwritten by the stale claim. The
          // existsSync+rename pair this replaced had a micro-TOCTOU:
          // rename() silently replaces a same-name destination, so a
          // concurrent link() enqueue in the gap lost its payload.
          fs.linkSync(claimed, Q + '/' + f);
        } catch (e2) {
          if (e2 && e2.code === 'EEXIST') {
            // a concurrent enqueue already re-created the root file -
            // this stale claim is a duplicate of the same draft:
            // drop it
            try { fs.unlinkSync(claimed); } catch (e3) {}
            note = 'retry: fresh queue file already exists - stale claim dropped';
          } else {
            // could not hand it back - leave the claim in
            // processing/; the ~10min stuck-claim pass reclaims it to
            // failed/ if it wedges
            note = 'retry move failed: ' + String(e2).slice(0, 120);
          }
        }
        if (!note) {
          // the link landed - the root now shares the claim's inode,
          // so drop the processing/ name to leave exactly one copy.
          // An unlink failure is not a requeue failure: the root file
          // publishes normally next tick and the leftover claim is
          // reclaimed to failed/ by the stuck-claim pass.
          try {
            fs.unlinkSync(claimed);
            note = 'retry: token service ' + (e.busy ? 'busy' : 'down') +
              ' - requeued for next tick';
          } catch (e3) {
            note = 'retry: requeued but claim copy left in processing/: ' +
              String(e3).slice(0, 100);
          }
        }
        const reason = (errStr + ' | ' + note).slice(0, 240);
        vkStatus(e.busy ? 'token_service_busy' : 'token_service_down',
          reason, f);
        log({ id: t.id, platform: t.platform, status: 'retry-requeued',
          note: note, error: errStr, retry: tries });
        out.push((t.id || f) + ' ' + t.platform + ' RETRY ' + tries +
          '/' + RETRY_MAX + ': ' + note);
        continue;
      }
      // the bumped counter could not be persisted - do NOT requeue
      // without it (an unbounded requeue is exactly what the bound
      // exists to prevent): fall through and fail the file
      // permanently, the same outcome as an exhausted budget.
    }
    mv(claimed, Q + '/failed/' + f, f);
    // transport loss AFTER wall.post was sent can mean the post is
    // already live while no post-created record exists - a re-approve
    // would wall.post a SECOND copy. Say so everywhere: the failed
    // line, the status file and the ledger record (maybe_live). Any
    // external_id the orphan probe recovered travels on e.orphan_id.
    const maybeLive = !!(e && e.maybe_live);
    const warn = maybeLive
      ? ' | POST MAY BE LIVE - check the VK wall before retrying' : '';
    // never leave a stale 'ok' behind - every failure path rewrites
    // vk_status. env_token_auth_error = the refresh service is down
    // AND the env fallback token was rejected too (vkCall flags both -
    // 'token_service_down' alone would mask the dead env credential);
    // token_service_down = host refresh service unreachable or unable
    // to mint a token; auth_error = VK API rejected the token
    // (error 5); vk_error = any other VK API rejection;
    // publish_error = transport / config / anything else. (A transient
    // retryable error only reaches here once its requeue budget is
    // exhausted or the counter could not be persisted - the
    // retryNote below makes the permanence explicit.)
    const retryNote = exhausted
      ? ' | token service retry budget exhausted (' + RETRY_MAX +
        ' requeues) - permanent failure; fix vk-token.service, ' +
        'then re-approve'
      : (e && e.retryable)
        ? ' | retry counter could not be persisted - failed ' +
          'permanently rather than requeue unbounded'
        : '';
    const reason = (errStr + warn + retryNote +
      (e && e.refresh_error ? ' | refresh: ' + e.refresh_error : '') +
      (e && e.env_token_auth ? ' | env token also rejected (error 5)' : '')
      ).slice(0, 240);
    if (e && e.token_service && e.env_token_auth)
      vkStatus('env_token_auth_error', reason, f);
    else if (e && e.token_service) vkStatus('token_service_down', reason, f);
    else if (e && e.vk_code === 5) vkStatus('auth_error', reason, f);
    else if (e && e.vk_code) vkStatus('vk_error', reason, f);
    else vkStatus('publish_error', reason, f);
    log({ id: t.id, platform: t.platform, status: 'failed',
      maybe_live: maybeLive, error: errStr });
    try {
      fs.appendFileSync(LEDGER, JSON.stringify({
        ts: new Date().toISOString(), id: t.id, platform: t.platform,
        status: 'failed', maybe_live: maybeLive,
        external_id: (e && e.orphan_id) || null, error: errStr
      }) + '\n');
    } catch (e2) {}
    out.push((t.id || f) + ' ' + t.platform + ' FAILED: ' +
      errStr.slice(0, 150) +
      (maybeLive ? ' | POST MAY BE LIVE - check VK wall before retry' : '') +
      (exhausted ? ' | retries exhausted - fix vk-token.service, re-approve' : ''));
  }
}
// merge this tick's per-file results: vk_status.json reports the WORST
// status plus the per-file detail array, so a clean file can no longer
// overwrite an earlier file's auth_error from the same run
if (tickFiles.length) {
  const rank = (s) => ({
    // 'skipped' is informational only - the file was parked, not a
    // driver outcome - so it ranks BELOW 'ok': a mixed tick reports
    // the real publish result, only a skip-only tick headlines it
    skipped: -1,
    ok: 0,
    // transient busy is informational only - the file was requeued,
    // not failed. It ranks above ok/no-work so a busy-only tick still
    // headlines it, but below EVERY real outcome: a busy file earlier
    // in the tick must never mask a publish_unverified or an error
    // status that came after it
    token_service_busy: 1,
    publish_unverified: 2, test_delete_failed: 3,
    publish_error: 4, vk_error: 5, auth_error: 6,
    token_service_down: 7,
    // two failures at once (refresh service down + env token dead) -
    // the worst headline a tick can report
    env_token_auth_error: 8
  })[s] ?? 4;
  const worst = tickFiles.reduce((a, b) =>
    rank(b.status) > rank(a.status) ? b : a, tickFiles[0]);
  try {
    const now = new Date().toISOString();
    writeJsonAtomic(VK_STATUS, {
      status: worst.status, ts: now, last_tick: now,
      file: worst.file, reason: worst.reason, files: tickFiles
    });
  } catch (e) {}
} else {
  // an empty tick (no queue files at all) reaches neither vkStatus
  // nor the merge above, so the status file kept the LAST non-empty
  // tick's ts forever - nothing proved the tick was still alive and
  // a stale headline read as current state. Rewrite the file with
  // the previous headline intact (a parked auth_error must not flip
  // to 'idle' just because the queue drained) and stamp last_tick
  // as the heartbeat; a fresh install with no prior file reports
  // 'idle'.
  try {
    let prev = {};
    try {
      prev = JSON.parse(fs.readFileSync(VK_STATUS, 'utf8')) || {};
    } catch (e) {}
    writeJsonAtomic(VK_STATUS, {
      status: prev.status || 'idle',
      ts: prev.ts || new Date().toISOString(),
      last_tick: new Date().toISOString(),
      file: prev.file || '', reason: prev.reason || '',
      files: Array.isArray(prev.files) ? prev.files : []
    });
  } catch (e) {}
}
if (out.length && chatId && token) {
  // Telegram rejects sendMessage over ~4096 chars and the catch below
  // swallows the failure - an unbounded tick report would be lost
  // silently. Cap it under the limit and mark the truncation so a cut
  // report reads as incomplete. Slice on code points (Array.from), not
  // UTF-16 units: a boundary split inside a surrogate pair would
  // produce a lone surrogate Telegram rejects as invalid text.
  let summary = 'Publish queue:\n' + out.join('\n');
  const summaryChars = Array.from(summary);
  if (summaryChars.length > 3900) {
    summary = summaryChars.slice(0, 3900).join('') +
      '\n... [truncated - ' + out.length + ' results total]';
  }
  try {
    await tg('sendMessage', { chat_id: chatId, text: summary });
  } catch (e) {
    // a lost tick report must not vanish without a trace:
    // the per-file records are already in publish.jsonl,
    // add a line saying the summary itself failed. Scrub
    // like every other error surface - the httpRequest
    // error can echo request details (bot-token URL).
    try {
      log({ action: 'summary-failed',
        error: scrub(e && (e.description || e.message) || e)
          .slice(0, 300) });
    } catch (e2) {}
  }
}
return [{ json: { processed: out.length, results: out } }];
